//! Internal support for selectors generated by `ModelSelect`.

use core::marker::PhantomData;
use std::rc::Rc;

use indexmap::IndexMap;
use itertools::Itertools;
pub use rusqlite::{Connection, Result as SqlResult, Row};
use rusqlite::{
    ToSql, params, params_from_iter,
    types::{FromSql, ToSqlOutput, Value},
};

use crate::{
    ModelSelectError,
    traits::{Query, max_rows_per_batch},
};

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum Direction {
    #[default]
    Asc,
    Desc,
    CaseInsensitiveAsc,
    CaseInsensitiveDesc,
}

impl Direction {
    const fn as_sql(self) -> &'static str {
        match self {
            Self::Asc => "ASC",
            Self::Desc => "DESC",
            Self::CaseInsensitiveAsc => "ASC",
            Self::CaseInsensitiveDesc => "DESC",
        }
    }

    const fn uses_case_insensitive_collation(self) -> bool {
        match self {
            Self::Asc | Self::Desc => false,
            Self::CaseInsensitiveAsc | Self::CaseInsensitiveDesc => true,
        }
    }
}

#[doc(hidden)]
pub enum HistoryRefValue {}

#[doc(hidden)]
pub enum OptionalHistoryRefValue {}

#[doc(hidden)]
pub trait IntoHistoryRef<Kind> {
    fn into_history_ref(self) -> Option<String>;
}

impl<T> IntoHistoryRef<HistoryRefValue> for T
where
    T: Into<String>,
{
    fn into_history_ref(self) -> Option<String> {
        Some(self.into())
    }
}

impl<T> IntoHistoryRef<OptionalHistoryRefValue> for Option<T>
where
    T: Into<String>,
{
    fn into_history_ref(self) -> Option<String> {
        self.map(Into::into)
    }
}

#[doc(hidden)]
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum SelectorBuildError {
    InvalidSelector(String),
    HistoryNotSupported { table_name: &'static str },
}

impl From<SelectorBuildError> for ModelSelectError {
    fn from(error: SelectorBuildError) -> Self {
        match error {
            SelectorBuildError::InvalidSelector(message) => Self::InvalidSelector(message),
            SelectorBuildError::HistoryNotSupported { table_name } => Self::HistoryNotSupported {
                table_name: table_name.to_string(),
            },
        }
    }
}

#[doc(hidden)]
pub fn sql_value(value: &impl ToSql) -> Result<Value, SelectorBuildError> {
    let value = value.to_sql().map_err(|error| {
        SelectorBuildError::InvalidSelector(format!(
            "failed to convert selector value to SQL: {error}"
        ))
    })?;
    match value {
        ToSqlOutput::Borrowed(value) => Value::try_from(value).map_err(|error| {
            SelectorBuildError::InvalidSelector(format!(
                "failed to copy selector SQL value: {error}"
            ))
        }),
        ToSqlOutput::Owned(value) => Ok(value),
        _ => Err(SelectorBuildError::InvalidSelector(
            "selector values must map to SQLite scalar values".to_string(),
        )),
    }
}

#[doc(hidden)]
#[derive(Clone, Debug, PartialEq)]
pub struct SqlFilter {
    pub clause: String,
    pub params: Vec<Value>,
    ordered_in: Option<OrderedSqlIn>,
}

impl SqlFilter {
    pub fn new(clause: impl Into<String>, params: Vec<Value>) -> Self {
        Self {
            clause: clause.into(),
            params,
            ordered_in: None,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
struct OrderedSqlIn {
    column: String,
    values: Vec<Value>,
}

#[doc(hidden)]
pub fn sql_in_filter(column: impl Into<String>, params: Vec<Value>) -> SqlFilter {
    if params.is_empty() {
        SqlFilter::new("0 = 1", params)
    } else {
        SqlFilter {
            clause: String::new(),
            params: Vec::new(),
            ordered_in: Some(OrderedSqlIn {
                column: column.into(),
                values: params,
            }),
        }
    }
}

#[derive(Clone, Debug)]
enum SqlParameter {
    Scalar(Value),
    Array(Rc<Vec<Value>>),
}

impl ToSql for SqlParameter {
    fn to_sql(&self) -> rusqlite::Result<ToSqlOutput<'_>> {
        match self {
            Self::Scalar(value) => value.to_sql(),
            Self::Array(values) => values.to_sql(),
        }
    }
}

#[doc(hidden)]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SqlOrder {
    column: String,
    direction: Direction,
}

impl SqlOrder {
    pub fn new(column: impl Into<String>, direction: Direction) -> Self {
        Self {
            column: column.into(),
            direction,
        }
    }
}

#[doc(hidden)]
#[derive(Clone, Copy, Debug)]
pub struct SqlSource {
    table_name: &'static str,
    alias: &'static str,
    source_id: &'static str,
    supports_history: bool,
    source_clause: fn(Option<&str>) -> String,
}

impl SqlSource {
    pub const fn new(
        table_name: &'static str,
        alias: &'static str,
        source_id: &'static str,
        supports_history: bool,
        source_clause: fn(Option<&str>) -> String,
    ) -> Self {
        Self {
            table_name,
            alias,
            source_id,
            supports_history,
            source_clause,
        }
    }

    fn clause(self, history_ref: Option<&str>) -> String {
        (self.source_clause)(history_ref)
    }

    pub fn table_name(self) -> &'static str {
        self.table_name
    }

    pub fn alias(self) -> &'static str {
        self.alias
    }

    fn supports_history(self) -> bool {
        self.supports_history
    }

    fn has_same_definition(self, other: Self) -> bool {
        self.table_name == other.table_name
            && self.alias == other.alias
            && self.source_id == other.source_id
            && self.supports_history == other.supports_history
    }
}

#[doc(hidden)]
#[derive(Clone, Debug)]
pub struct SqlJoin {
    source: SqlSource,
    condition: String,
}

impl SqlJoin {
    fn new(source: SqlSource, condition: String) -> Self {
        Self { source, condition }
    }

    fn append_sql(&self, query: &mut String, history_ref: Option<&str>) {
        query.push_str(" JOIN ");
        query.push_str(&self.source.clause(history_ref));
        query.push_str(" ON ");
        query.push_str(&self.condition);
    }

    pub fn source(&self) -> SqlSource {
        self.source
    }
}

#[doc(hidden)]
#[derive(Clone, Debug, Default)]
pub struct SqlJoins {
    joins: IndexMap<&'static str, SqlJoin>,
}

impl SqlJoins {
    pub fn len(&self) -> usize {
        self.joins.len()
    }

    pub fn is_empty(&self) -> bool {
        self.joins.is_empty()
    }

    pub fn iter(&self) -> impl Iterator<Item = &SqlJoin> {
        self.joins.values()
    }

    pub fn insert(&mut self, join: SqlJoin) -> Result<(), SelectorBuildError> {
        let alias = join.source.alias();
        if let Some(existing) = self.joins.get(alias) {
            if !existing.source.has_same_definition(join.source)
                || existing.condition != join.condition
            {
                return Err(SelectorBuildError::InvalidSelector(format!(
                    "cannot use SQL source alias `{alias}` for different joins"
                )));
            }
        } else {
            self.joins.insert(alias, join);
        }
        Ok(())
    }

    pub fn extend_from(&mut self, joins: &Self) -> Result<(), SelectorBuildError> {
        for join in joins.iter() {
            self.insert(join.clone())?;
        }
        Ok(())
    }
}

#[doc(hidden)]
pub trait SelectQuery {
    fn connection(&self) -> &Connection;

    fn source(&self) -> SqlSource;

    fn error(&self) -> Option<&SelectorBuildError>;

    fn history_ref(&self) -> Option<&str>;

    fn joins(&self) -> &SqlJoins;

    fn filters(&self) -> &[SqlFilter];

    fn order_by(&self) -> &[SqlOrder];

    fn limit(&self) -> Option<u32>;

    fn offset(&self) -> u32;

    fn select_clause(&self) -> String {
        select_all_sql(self.source().alias())
    }
}

#[doc(hidden)]
#[derive(Debug, Eq, PartialEq)]
pub struct SelectField<M, T, JoinType = T> {
    table_name: &'static str,
    alias: &'static str,
    column: &'static str,
    field: PhantomData<fn() -> (M, T)>,
    join_type: PhantomData<fn() -> JoinType>,
}

impl<M, T, JoinType> SelectField<M, T, JoinType> {
    pub const fn new(table_name: &'static str, alias: &'static str, column: &'static str) -> Self {
        Self {
            table_name,
            alias,
            column,
            field: PhantomData,
            join_type: PhantomData,
        }
    }

    pub const fn column(self) -> &'static str {
        self.column
    }

    pub const fn table_name(self) -> &'static str {
        self.table_name
    }

    pub const fn alias(self) -> &'static str {
        self.alias
    }
}

impl<M, T, JoinType> Clone for SelectField<M, T, JoinType> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<M, T, JoinType> Copy for SelectField<M, T, JoinType> {}

#[doc(hidden)]
pub trait ProjectionField {
    type Output;

    fn table_name(&self) -> &'static str;

    fn alias(&self) -> &'static str;

    fn column(&self) -> &'static str;

    fn process_row(&self, row: &Row, index: usize) -> rusqlite::Result<Self::Output>;
}

impl<M, T, JoinType> ProjectionField for SelectField<M, T, JoinType>
where
    T: FromSql,
{
    type Output = T;

    fn table_name(&self) -> &'static str {
        self.table_name
    }

    fn alias(&self) -> &'static str {
        self.alias
    }

    fn column(&self) -> &'static str {
        self.column
    }

    fn process_row(&self, row: &Row, index: usize) -> rusqlite::Result<Self::Output> {
        row.get(index)
    }
}

#[doc(hidden)]
pub trait SelectableModel: Sized {
    fn table_name() -> &'static str;

    fn alias() -> &'static str;

    fn columns() -> &'static [&'static str];

    fn process_row(row: &Row, offset: usize) -> SqlResult<Self>;
}

#[doc(hidden)]
pub trait ModelSelectSource: Sized + 'static {
    type Selector<'conn>: SelectQuery;

    fn selector(conn: &Connection) -> Self::Selector<'_>;
}

#[doc(hidden)]
pub trait SelectProjection {
    type Output;

    fn fields(&self) -> Vec<(&'static str, &'static str, &'static str)>;

    fn process_row(&self, row: &Row) -> rusqlite::Result<Self::Output>;
}

impl<M, T, JoinType> SelectProjection for SelectField<M, T, JoinType>
where
    T: FromSql,
{
    type Output = T;

    fn fields(&self) -> Vec<(&'static str, &'static str, &'static str)> {
        vec![(self.table_name, self.alias, self.column)]
    }

    fn process_row(&self, row: &Row) -> rusqlite::Result<Self::Output> {
        row.get(0)
    }
}

macro_rules! impl_select_projection_for_tuple {
    ($($field:ident:$index:tt),+) => {
        impl<$($field),+> SelectProjection for ($($field,)+)
        where
            $($field: ProjectionField,)+
        {
            type Output = ($(<$field as ProjectionField>::Output,)+);

            fn fields(&self) -> Vec<(&'static str, &'static str, &'static str)> {
                vec![$(
                    (
                        self.$index.table_name(),
                        self.$index.alias(),
                        self.$index.column(),
                    )
                ),+]
            }

            fn process_row(&self, row: &Row) -> rusqlite::Result<Self::Output> {
                Ok(($(self.$index.process_row(row, $index)?,)+))
            }
        }
    };
}

