#[doc(hidden)]
pub struct SelectedFields<S, P> {
    select: S,
    projection: P,
}

impl<S, P> SelectedFields<S, P> {
    pub fn new(select: S, projection: P) -> Self {
        Self { select, projection }
    }
}

impl<S, P> SelectedFields<S, P>
where
    S: SelectQuery,
    P: SelectProjection,
{
    pub fn load(self) -> Result<Vec<P::Output>, ModelSelectError> {
        let Self { select, projection } = self;
        load_projection(select, projection.fields(), |row| {
            projection.process_row(row)
        })
    }
}

#[doc(hidden)]
pub struct SelectedModels<S, P> {
    select: S,
    projection: PhantomData<fn() -> P>,
}

impl<S, P> SelectedModels<S, P> {
    pub fn new(select: S) -> Self {
        Self {
            select,
            projection: PhantomData,
        }
    }
}

impl<S, P> SelectedModels<S, P>
where
    S: SelectQuery,
    P: ModelProjection,
{
    pub fn load(self) -> Result<Vec<P::Output>, ModelSelectError> {
        load_projection(self.select, P::fields(), P::process_row)
    }
}

fn load_projection<S, T>(
    select: S,
    fields: Vec<(&'static str, &'static str, &'static str)>,
    process_row: impl FnMut(&Row) -> SqlResult<T>,
) -> Result<Vec<T>, ModelSelectError>
where
    S: SelectQuery,
{
    if let Some(error) = select.error() {
        return Err(error.clone().into());
    }
    validate_projection_sources(&select, &fields)?;
    let select_clause = fields
        .iter()
        .map(|(_, alias, column)| qualify_sql_column(alias, column))
        .join(", ");
    let (query, params) = render_query(&select, select_clause, None)?;
    query_rows(select.connection(), &query, params, process_row)
}

fn validate_projection_sources<S>(
    select: &S,
    fields: &[(&'static str, &'static str, &'static str)],
) -> Result<(), ModelSelectError>
where
    S: SelectQuery,
{
    for (table_name, alias, _) in fields {
        let source = select.source();
        let source_is_available = source.table_name() == *table_name && source.alias() == *alias
            || select.joins().iter().any(|join| {
                let source = join.source();
                source.table_name() == *table_name && source.alias() == *alias
            });
        if !source_is_available {
            return Err(ModelSelectError::ProjectionSourceNotSelected {
                table_name: (*table_name).to_string(),
                alias: (*alias).to_string(),
            });
        }
    }
    Ok(())
}

#[doc(hidden)]
pub fn load<M, S>(conn: &Connection, select: &S) -> Result<Vec<M>, ModelSelectError>
where
    M: Query<Model = M>,
    S: SelectQuery,
{
    let (query, params) = render_query(select, select.select_clause(), None)?;
    query_rows(conn, &query, params, M::process_row)
}

#[doc(hidden)]
pub fn get<M, S>(conn: &Connection, select: &S) -> Result<Option<M>, ModelSelectError>
where
    M: Query<Model = M>,
    S: SelectQuery,
{
    let (query, params) = render_query(select, select.select_clause(), Some(2))?;
    let mut rows = query_rows(conn, &query, params, M::process_row)?;
    match rows.len() {
        0 => Ok(None),
        1 => Ok(rows.pop()),
        _ => Err(ModelSelectError::MultipleResults),
    }
}

fn render_query<S>(
    select: &S,
    select_clause: String,
    maximum_rows: Option<u32>,
) -> Result<(String, Vec<SqlParameter>), ModelSelectError>
where
    S: SelectQuery,
{
    if let Some(error) = select.error() {
        return Err(error.clone().into());
    }
    if select.history_ref().is_some() {
        for source in
            core::iter::once(select.source()).chain(select.joins().iter().map(|join| join.source()))
        {
            if !source.supports_history() {
                return Err(SelectorBuildError::HistoryNotSupported {
                    table_name: source.table_name(),
                }
                .into());
            }
        }
    }

    let mut query = format!(
        "SELECT {select_clause} FROM {}",
        select.source().clause(select.history_ref()),
    );
    for join in select.joins().iter() {
        join.append_sql(&mut query, select.history_ref());
    }

    let mut params = select
        .history_ref()
        .map(|history_ref| vec![SqlParameter::Scalar(Value::from(history_ref.to_string()))])
        .unwrap_or_default();
    let filters = select.filters();
    let batch_size = max_rows_per_batch(select.connection(), 1);
    for (index, ordered_in) in filters
        .iter()
        .filter_map(|filter| filter.ordered_in.as_ref())
        .enumerate()
    {
        append_ordered_in_join(&mut query, &mut params, ordered_in, index, batch_size);
    }

    if filters.iter().any(|filter| !filter.clause.is_empty()) {
        query.push_str(" WHERE ");
        for (index, filter) in filters
            .iter()
            .filter(|filter| !filter.clause.is_empty())
            .enumerate()
        {
            if index > 0 {
                query.push_str(" AND ");
            }
            query.push_str(&filter.clause);
            params.extend(filter.params.iter().cloned().map(SqlParameter::Scalar));
        }
    }

    let order_by = select.order_by();
    let ordered_in_count = filters
        .iter()
        .filter(|filter| filter.ordered_in.is_some())
        .count();
    if ordered_in_count > 0 || !order_by.is_empty() {
        query.push_str(" ORDER BY ");
        for index in 0..ordered_in_count {
            if index > 0 {
                query.push_str(", ");
            }
            query.push_str(&qualify_sql_column(
                &format!("__model_select_in_{index}"),
                "position",
            ));
            query.push_str(" ASC");
        }
        for (index, order) in order_by.iter().enumerate() {
            if ordered_in_count > 0 || index > 0 {
                query.push_str(", ");
            }
            query.push_str(&order.column);
            if order.direction.uses_case_insensitive_collation() {
                query.push_str(" COLLATE NOCASE");
            }
            query.push(' ');
            query.push_str(order.direction.as_sql());
        }
    }

    let effective_limit = maximum_rows.or(select.limit());
    if let Some(limit) = effective_limit {
        query.push_str(" LIMIT ?");
        params.push(SqlParameter::Scalar(Value::from(i64::from(limit))));
    }
    let offset = select.offset();
    if offset > 0 {
        if effective_limit.is_none() {
            query.push_str(" LIMIT -1");
        }
        query.push_str(" OFFSET ?");
        params.push(SqlParameter::Scalar(Value::from(i64::from(offset))));
    }

    Ok((query, params))
}

#[doc(hidden)]
pub fn delete_by_ids(
    conn: &Connection,
    table_name: &str,
    primary_key: &str,
    values: Vec<Value>,
) -> Result<usize, ModelSelectError> {
    if values.is_empty() {
        return Ok(0);
    }

    let query = format!(
        "DELETE FROM {} WHERE {} IN rarray(?1)",
        quote_sql_identifier(table_name),
        quote_sql_identifier(primary_key),
    );
    let batch_size = max_rows_per_batch(conn, 1);
    let mut deleted = 0;
    let mut statement = conn.prepare(&query)?;
    for chunk in values.chunks(batch_size) {
        deleted += statement.execute(params![Rc::new(chunk.to_vec())])?;
    }
    Ok(deleted)
}

fn append_ordered_in_join(
    query: &mut String,
    params: &mut Vec<SqlParameter>,
    ordered_in: &OrderedSqlIn,
    index: usize,
    batch_size: usize,
) {
    let values_alias = quote_sql_identifier(&format!("__model_select_in_values_{index}"));
    let order_alias = format!("__model_select_in_{index}");
    query.push_str(" JOIN (SELECT \"value\", MIN(\"position\") AS \"position\" FROM (");
    for (chunk_index, chunk) in ordered_in.values.chunks(batch_size).enumerate() {
        if chunk_index > 0 {
            query.push_str(" UNION ALL ");
        }
        let position_offset = chunk_index * batch_size;
        query.push_str(&format!(
            "SELECT \"value\", \"rowid\" + {position_offset} AS \"position\" FROM rarray(?)"
        ));
        params.push(SqlParameter::Array(Rc::new(chunk.to_vec())));
    }
    query.push_str(") AS ");
    query.push_str(&values_alias);
    query.push_str(" GROUP BY \"value\") AS ");
    query.push_str(&quote_sql_identifier(&order_alias));
    query.push_str(" ON ");
    query.push_str(&ordered_in.column);
    query.push_str(" = ");
    query.push_str(&qualify_sql_column(&order_alias, "value"));
}

fn query_rows<T>(
    conn: &Connection,
    query: &str,
    params: Vec<SqlParameter>,
    mut process_row: impl FnMut(&Row) -> rusqlite::Result<T>,
) -> Result<Vec<T>, ModelSelectError> {
    let mut statement = conn.prepare(query)?;
    let rows = statement.query_map(params_from_iter(params), |row| process_row(row))?;
    rows.collect::<Result<Vec<_>, _>>().map_err(Into::into)
}

#[doc(hidden)]
pub fn qualify_sql_column(alias: &str, column: &str) -> String {
    format!(
        "{}.{}",
        quote_sql_identifier(alias),
        quote_sql_identifier(column),
    )
}

#[doc(hidden)]
pub fn select_all_sql(alias: &str) -> String {
    format!("{}.*", quote_sql_identifier(alias))
}

#[doc(hidden)]
pub fn default_sql_source(
    table_name: &str,
    history_table_name: Option<&str>,
    alias: &str,
    history_ref: Option<&str>,
) -> String {
    let source = if history_ref.is_some() {
        let history_table_name = history_table_name.expect("should support history ref queries");
        quote_sql_identifier(&format!("dolt_at_{history_table_name}")) + "(:history_ref)"
    } else {
        quote_sql_identifier(table_name)
    };
    format!("{source} AS {}", quote_sql_identifier(alias))
}

#[doc(hidden)]
pub fn sql_join_on<SourceModel, SourceType, JoinedModel, JoinedType, JoinType>(
    existing_sources: &[SqlSource],
    joined_source: SqlSource,
    source_field: SelectField<SourceModel, SourceType, JoinType>,
    joined_field: SelectField<JoinedModel, JoinedType, JoinType>,
) -> Result<SqlJoin, SelectorBuildError> {
    if existing_sources
        .first()
        .is_some_and(|source| source.alias() == joined_source.alias())
    {
        return Err(SelectorBuildError::InvalidSelector(format!(
            "cannot join the base SQL source alias `{}`",
            joined_source.alias(),
        )));
    }
    if !existing_sources.iter().any(|source| {
        source.table_name() == source_field.table_name() && source.alias() == source_field.alias()
    }) {
        return Err(SelectorBuildError::InvalidSelector(format!(
            "cannot join from unselected SQL source `{} AS {}`",
            source_field.table_name(),
            source_field.alias(),
        )));
    }
    if joined_source.table_name() != joined_field.table_name()
        || joined_source.alias() != joined_field.alias()
    {
        return Err(SelectorBuildError::InvalidSelector(format!(
            "joined field source `{} AS {}` does not match selector source `{} AS {}`",
            joined_field.table_name(),
            joined_field.alias(),
            joined_source.table_name(),
            joined_source.alias(),
        )));
    }

    let condition = format!(
        "{} = {}",
        qualify_sql_column(source_field.alias(), source_field.column()),
        qualify_sql_column(joined_field.alias(), joined_field.column()),
    );
    Ok(SqlJoin::new(joined_source, condition))
}

fn quote_sql_identifier(identifier: &str) -> String {
    format!("\"{}\"", identifier.replace('"', "\"\""))
}

#[cfg(test)]
mod tests {
    use super::{
        SelectField, SelectorBuildError, SqlJoins, SqlSource, default_sql_source,
        qualify_sql_column, select_all_sql, sql_join_on,
    };

    fn child_source_clause(_history_ref: Option<&str>) -> String {
        "selector_children".to_string()
    }

    fn parent_source_clause(_history_ref: Option<&str>) -> String {
        "selector_parents".to_string()
    }

    #[test]
    fn test_explicit_join_quotes_field_identifiers_without_database_metadata() {
        let child_source = SqlSource::new(
            "selector_children",
            "children.alias",
            "tests::children",
            true,
            child_source_clause,
        );
        let parent_source = SqlSource::new(
            "selector_parents",
            "parents\" --",
            "tests::parents",
            true,
            parent_source_clause,
        );
        let source_field = SelectField::<(), i64>::new(
            "selector_children",
            "children.alias",
            "source\" OR attacker_effect()",
        );
        let joined_field =
            SelectField::<(), i64>::new("selector_parents", "parents\" --", "target.column");

        let join = sql_join_on(&[child_source], parent_source, source_field, joined_field)
            .expect("should create an explicit join");
        assert_eq!(
            join.condition,
            "\"children.alias\".\"source\"\" OR attacker_effect()\" = \"parents\"\" --\".\"target.column\"",
        );
    }

    #[test]
    fn test_duplicate_identical_joins_are_deduplicated_in_insertion_order() {
        let child_source = SqlSource::new(
            "selector_children",
            "selector_children",
            "tests::children",
            true,
            child_source_clause,
        );
        let later_source = SqlSource::new(
            "later_parents",
            "z_parents",
            "tests::later_parents",
            true,
            parent_source_clause,
        );
        let earlier_source = SqlSource::new(
            "earlier_parents",
            "a_parents",
            "tests::earlier_parents",
            true,
            parent_source_clause,
        );
        let source_field =
            SelectField::<(), i64>::new("selector_children", "selector_children", "parent_id");
        let later_field = SelectField::<(), i64>::new("later_parents", "z_parents", "id");
        let earlier_field = SelectField::<(), i64>::new("earlier_parents", "a_parents", "id");
        let later_join = sql_join_on(&[child_source], later_source, source_field, later_field)
            .expect("should create the later join");
        let earlier_join =
            sql_join_on(&[child_source], earlier_source, source_field, earlier_field)
                .expect("should create the earlier join");
        let mut joins = SqlJoins::default();

        joins
            .insert(later_join.clone())
            .expect("should insert the later join");
        joins
            .insert(earlier_join)
            .expect("should insert the earlier join");
        joins
            .insert(later_join)
            .expect("should deduplicate the later join");

        assert_eq!(joins.len(), 2);
        assert_eq!(
            joins
                .iter()
                .map(|join| join.source().alias())
                .collect::<Vec<_>>(),
            vec!["z_parents", "a_parents"],
        );
    }

    #[test]
    fn test_duplicate_alias_with_different_join_is_rejected() {
        let child_source = SqlSource::new(
            "selector_children",
            "selector_children",
            "tests::children",
            true,
            child_source_clause,
        );
        let parent_source = SqlSource::new(
            "selector_parents",
            "selector_parents",
            "tests::parents",
            true,
            parent_source_clause,
        );
        let joined_field =
            SelectField::<(), i64>::new("selector_parents", "selector_parents", "id");
        let first_join = sql_join_on(
            &[child_source],
            parent_source,
            SelectField::<(), i64>::new("selector_children", "selector_children", "parent_id"),
            joined_field,
        )
        .expect("should create the first join");
        let second_join = sql_join_on(
            &[child_source],
            parent_source,
            SelectField::<(), i64>::new(
                "selector_children",
                "selector_children",
                "other_parent_id",
            ),
            joined_field,
        )
        .expect("should create the second join");
        let mut joins = SqlJoins::default();

        joins
            .insert(first_join)
            .expect("should insert the first join");
        let error = joins
            .insert(second_join)
            .expect_err("should reject a conflicting join");

        assert_eq!(
            error,
            SelectorBuildError::InvalidSelector(
                "cannot use SQL source alias `selector_parents` for different joins".to_string(),
            )
        );
    }

    #[test]
    fn test_duplicate_alias_with_different_source_is_rejected() {
        let child_source = SqlSource::new(
            "selector_children",
            "selector_children",
            "tests::children",
            true,
            child_source_clause,
        );
        let first_source = SqlSource::new(
            "selector_parents",
            "shared_parents",
            "tests::parents",
            true,
            parent_source_clause,
        );
        let second_source = SqlSource::new(
            "alternate_parents",
            "shared_parents",
            "tests::alternate_parents",
            true,
            parent_source_clause,
        );
        let source_field =
            SelectField::<(), i64>::new("selector_children", "selector_children", "parent_id");
        let first_join = sql_join_on(
            &[child_source],
            first_source,
            source_field,
            SelectField::<(), i64>::new("selector_parents", "shared_parents", "id"),
        )
        .expect("should create the first join");
        let second_join = sql_join_on(
            &[child_source],
            second_source,
            source_field,
            SelectField::<(), i64>::new("alternate_parents", "shared_parents", "id"),
        )
        .expect("should create the second join");
        let mut joins = SqlJoins::default();

        joins
            .insert(first_join)
            .expect("should insert the first join");
        let error = joins
            .insert(second_join)
            .expect_err("should reject a conflicting source");

        assert_eq!(
            error,
            SelectorBuildError::InvalidSelector(
                "cannot use SQL source alias `shared_parents` for different joins".to_string(),
            )
        );
    }

    #[test]
    fn test_structured_sql_helpers_quote_every_identifier() {
        assert_eq!(
            qualify_sql_column("source.alias", "target.column"),
            "\"source.alias\".\"target.column\"",
        );
        assert_eq!(select_all_sql("source\"alias"), "\"source\"\"alias\".*");
        assert_eq!(
            default_sql_source("table name", Some("history.table"), "select", None),
            "\"table name\" AS \"select\"",
        );
        assert_eq!(
            default_sql_source("table name", Some("history.table"), "select", Some("main"),),
            "\"dolt_at_history.table\"(:history_ref) AS \"select\"",
        );
    }
}
